SET NAMES utf8mb4;
START TRANSACTION;
UPDATE mdm_product SET preparation_controlled=1 WHERE product_code IN ('LAMP-HEAD','LAMP-ARM','LAMP-BASE-L100','LAMP-BASE-L200','LAMP-L100','LAMP-L200') AND deleted_flag=0;
